import "server-only";

/**
 * Bank soal quiz & exam. Kunci = id quiz di lib/data.ts (string).
 * `answer` = indeks opsi yang benar (0-based). Jawaban TIDAK pernah dikirim ke browser
 * sebelum quiz dikumpulkan; penilaian dilakukan di server (lib/learning.ts).
 *
 * Cara menambah soal: tambahkan entri baru di BANK dengan id quiz yang bersangkutan.
 */

export type QuizQuestion = {
  q: string;
  options: string[];
  /** Satu angka = pilihan tunggal. Array = pilihan ganda (semua harus tepat untuk benar). */
  answer: number | number[];
  explain?: string;
};

export type PublicQuestion = { q: string; options: string[]; multi: boolean };

