/** Soal milik quiz ini, atau null kalau belum ditulis. */
export function getQuizBank(quizId: string): QuizQuestion[] | null {
  const own = BANK[quizId];
  if (own && own.length > 0) return own;
  if (process.env.NODE_ENV !== "production") return SAMPLE;
  return null;
}

export function toPublic(questions: QuizQuestion[]): PublicQuestion[] {
  return questions.map(({ q, options, answer }) => ({ q, options, multi: Array.isArray(answer) }));
}